async function comp6(name) { const page = await figma.getNodeByIdAsync(PAGES.components); await page.loadAsync(); return page.findOne((n) => n.type === 'COMPONENT' && n.name === name); }
async function avatarDot(initial, tintBg, tintInk, size = 32) {
  const a = row(0, 'Avatar'); a.resize(size, size); a.primaryAxisSizingMode = 'FIXED'; a.counterAxisSizingMode = 'FIXED'; a.primaryAxisAlignItems = 'CENTER'; a.cornerRadius = 999; a.fills = [fill(tintBg)];
  a.appendChild(await text(initial, 'Label/Small', tintInk)); return a;
}
async function optionRow(name, sub, initial, tint, { selected = false, active = false, added = false } = {}) {
  const r = row(12, name); pad(r, 6, 10); r.minHeight = 48; r.cornerRadius = 10; r.fills = active ? [fill('surface/raised')] : [];
  r.appendChild(await avatarDot(initial, `person/${tint}-bg`, `person/${tint}-ink`));
  const c = col(0); c.appendChild(await text(name, selected ? 'Body/Strong' : 'Body/Regular', selected ? 'brand/deep' : added ? 'text/muted' : 'text/primary')); if (sub) add(c, await text(sub, 'Body/Small', 'text/muted')); grow(r, c);
  if (selected) r.appendChild(await icon('check', 18, 'brand/ink'));
  if (added) r.appendChild(await text('Added', 'Body/Small', 'text/muted'));
  return r;
}
function floating(name, w = 350) {
  const p = figma.createComponent(); p.name = name; p.layoutMode = 'VERTICAL'; p.itemSpacing = 0; p.resize(w, 10); p.counterAxisSizingMode = 'FIXED'; p.primaryAxisSizingMode = 'AUTO';
  pad(p, 6); p.cornerRadius = 16; p.fills = [fill('surface/card')]; outline(p);
  p.effects = [{ type: 'DROP_SHADOW', color: { r: 0.07, g: 0.13, b: 0.11, a: 0.06 }, offset: { x: 0, y: 6 }, radius: 12, spread: 0, visible: true, blendMode: 'NORMAL' }];
  return p;
}
async function buildDropdowns() {
  const page = await figma.getNodeByIdAsync(PAGES.components); await page.loadAsync();
  page.findAll((n) => n.name === 'Dropdowns').forEach((n) => n.remove());
  const board = row(32, 'Dropdowns'); board.counterAxisAlignItems = 'MIN'; pad(board, 32); board.cornerRadius = 24; board.fills = [fill('surface/raised')];
  page.appendChild(board); board.x = 0; board.y = Math.max(0, ...page.children.filter((n) => n !== board).map((n) => n.y + n.height)) + 120;

  const paidBy = floating('Popover / Paid by');
  for (const [n, sub, i, t, o] of [['Samay (you)', null, 'S', 'a', { selected: true, active: true }], ['Ayushi', 'ayushi@fintrackr.app', 'A', 'b', {}], ['Kartik', 'kartik.rao@fintrackr.app', 'K', 'a', {}]]) add(paidBy, await optionRow(n, sub, i, t, o));
  paidBy.description = 'Anchored select (role=listbox) under its field, above it when there is no room. 3+ people; 2 people keep the segment. Arrows/Home/End move, Enter picks, Esc or Tab closes, focus returns to the field.';
  const results = floating('Dropdown / Member search · Results');
  add(results, await optionRow('Ayushi Dongre', 'ayushi@fintrackr.app', 'A', 'b', { added: true, active: true }));
  add(results, await optionRow('Ayaan Shah', 'ayaan@fintrackr.app', 'A', 'a'));
  results.description = 'Combobox: the input keeps focus; results open under it (aria-activedescendant). The typed letters are underlined in each match; people already added are marked and disabled.';
  const status = async (name, str, spinner) => {
    const d = floating(name); const r = row(10, 'Status'); pad(r, 6, 10); r.minHeight = 48;
    if (spinner) { const s = figma.createEllipse(); s.name = 'Spinner'; s.resize(16, 16); s.fills = []; s.strokes = [fill('text/muted')]; s.strokeWeight = 2; s.dashPattern = [36, 14]; r.appendChild(s); }
    grow(r, await text(str, 'Body/Regular', 'text/muted')); add(d, r); return d;
  };
  const searching = await status('Dropdown / Member search · Searching', 'Searching…', true);
  const none = await status('Dropdown / Member search · No match', 'No one matches “zubin”. They need a FinTrackr account first.', false);
  const switcher = await sheetComp('Switch account', 'Switch account', async (c) => {
    for (const [n, sub, ic, cur] of [['Personal', 'Just me · ₹1,75,505', 'wallet', false], ['Ghar', 'Shared with Ayushi · ₹18,846', 'users', true]]) {
      const r = row(12, n); pad(r, 10, 12); r.minHeight = 60; r.cornerRadius = 14; r.fills = cur ? [fill('brand/soft')] : [];
      r.appendChild(await icon(ic, 22, 'text/primary')); const t = col(2); t.appendChild(await text(n, 'Body/Regular')); t.appendChild(await text(sub, 'Body/Small', 'text/muted')); grow(r, t);
      if (cur) r.appendChild(await icon('check', 20, 'brand/ink')); add(c, r);
    }
    add(c, await pairActions(await btn('Manage accounts', 'Secondary/Medium'), await btn('New account', 'Primary/Medium')));
  });
  for (const c of [paidBy, results, searching, none, switcher]) board.appendChild(c);
  return { paidBy, results, searching, none, switcher };
}

