async function routeFrame(name) {
  for (const id of ROUTE_SECTIONS) { const sec = await figma.getNodeByIdAsync(id); const f = sec?.children.find((c) => c.name === name); if (f) return f; }
  throw new Error(`route screen "${name}" not found`);
}
function showOverlay(f, sheetComponent, label) { const o = overlay(f, sheetComponent, label); o.name = `Overlay · ${label}`; o.visible = true; return o; }
function placeAbsolute(f, node, x, y) { f.appendChild(node); node.layoutPositioning = 'ABSOLUTE'; node.x = x; node.y = y; return node; }

async function buildStates(dd) {
  const need = async (n) => { const c = await comp6(n); if (!c) throw new Error(`component "${n}" missing — run rounds 4 and 5 first`); return c; };
  const K = {};
  for (const [k, n] of [['detail', 'Sheet / Transaction detail'], ['confirm', 'Sheet / Delete transaction'], ['filters', 'Sheet / Filters'], ['period', 'Sheet / Period'], ['record', 'Sheet / Record payment'], ['pause', 'Sheet / Pause schedule'], ['delSched', 'Sheet / Delete schedule'], ['date', 'Sheet / Date'], ['range', 'Sheet / Date range'], ['skDay', 'Skeleton / Day card'], ['skRow', 'Skeleton / Row'], ['saving', 'Button / Saving'], ['offline', 'Banner / Offline'], ['snack', 'Snackbar']]) K[k] = await need(n);

  const screens = await figma.getNodeByIdAsync(PAGES.screens);
  screens.children.filter((n) => n.type === 'SECTION' && n.name.startsWith('07 · States')).forEach((n) => n.remove());
  const top = Math.max(...screens.children.filter((n) => n.type === 'SECTION').map((n) => n.y + n.height)) + 240;
  const sec = figma.createSection(); sec.name = '07 · States (not routes)'; sec.x = 0; sec.y = top; screens.appendChild(sec);

  const rows = [
    ['Popovers & sheets', [
      ['Transactions', 'Transaction detail', (f) => showOverlay(f, K.detail, 'Transaction detail')],
      ['Transactions', 'Delete transaction', (f) => showOverlay(f, K.confirm, 'Delete transaction')],
      ['Transactions', 'Filters', (f) => showOverlay(f, K.filters, 'Filters')],
      ['Transactions', 'Period', (f) => showOverlay(f, K.period, 'Period')],
      ['View recurring', 'Record payment', (f) => showOverlay(f, K.record, 'Record payment')],
      ['View recurring', 'Pause schedule', (f) => showOverlay(f, K.pause, 'Pause schedule')],
      ['View recurring', 'Delete schedule', (f) => showOverlay(f, K.delSched, 'Delete schedule')],
      ['Home · Dashboard', 'Switch account', (f) => showOverlay(f, dd.switcher, 'Switch account')],
    ]],
    ['Dropdowns & date pickers', [
      ['Add transaction', 'Paid by (3 people)', async (f) => {
        const pb = f.findOne((n) => n.type === 'FRAME' && n.name === 'Paid by'); if (!pb) throw new Error('Paid by field not found');
        pb.children.filter((c) => c.name === 'Segmented').forEach((c) => { c.visible = false; });
        const sel = await input(null, 'Samay (you)', 'user'); sel.name = 'Select · Paid by'; pb.appendChild(sel); sel.layoutSizingHorizontal = 'FILL';
        refitClone(f);
        const p = dd.paidBy.createInstance(); const y = relY(sel, f);
        placeAbsolute(f, p, 20, y + sel.height + p.height + 6 < f.height - 80 ? y + sel.height + 6 : y - p.height - 6);
      }],
      ...[['Invite · results', dd.results, 'ay'], ['Invite · searching', dd.searching, 'ay'], ['Invite · no match', dd.none, 'zubin']].map(([label, c, q]) => ['Onboarding', label, async (f) => {
        const inv = f.findOne((n) => n.type === 'FRAME' && n.name === 'Invite'); const field = inv?.findOne((n) => n.type === 'INSTANCE');
        if (!field) throw new Error('Invite field not found');
        field.setProperties({ [C.input.value]: q, [C.input.icon]: IC.search });
        const p = c.createInstance(); placeAbsolute(f, p, 20, relY(field, f) + field.height + 6);
      }]),
      ['Add transaction', 'Date', (f) => showOverlay(f, K.date, 'Date')],
      ['Transactions', 'Custom range', (f) => showOverlay(f, K.range, 'Custom range')],
    ]],
    ['Loading & system', [
      ['Home · Dashboard', 'Loading', async (f) => {
        const sum = f.findOne((n) => n.type === 'FRAME' && n.name === 'Summary card');
        const H = stateLayer(f, 'Loading', sum ? relY(sum, f) : 90); H.name = 'Loading'; H.itemSpacing = 20;
        add(H, await skeletonSummary()); const b = newCard('Bills skeleton'); add(H, b); for (let i = 0; i < 2; i++) { const r = K.skRow.createInstance(); add(b, r); if (i) ruleTop(r); }
        add(H, K.skDay.createInstance());
      }],
      ['Transactions', 'Loading', async (f) => {
        const who = f.findOne((n) => n.type === 'FRAME' && n.name === 'Out by person');
        const L = stateLayer(f, 'Loading', who ? relY(who, f) : 180, 'Footer'); L.name = 'Loading';
        const footer = f.children.find((c) => c.name === 'Footer'); if (footer) f.insertChild(f.children.indexOf(footer), L);
        for (let i = 0; i < 3; i++) add(L, K.skDay.createInstance());
      }],
      ['Recurring', 'Loading', async (f) => {
        const R = stateLayer(f, 'Loading', 64); R.name = 'Loading'; R.itemSpacing = 20; pad(R, 4, 20);
        add(R, await skeletonSummary()); const c = newCard('List skeleton'); add(R, c); for (let i = 0; i < 5; i++) { const r = K.skRow.createInstance(); add(c, r); if (i) ruleTop(r); }
      }],
      ['Transactions', 'Offline', async (f) => {
        const body = f.children.find((c) => c.name === 'Content'); const b = K.offline.createInstance(); body.insertChild(0, b); b.layoutSizingHorizontal = 'FILL'; refitClone(f);
      }],
      ['Transactions', 'Empty period', async (f) => {
        const body = f.children.find((c) => c.name === 'Content');
        for (const n of ['Out by person', 'List', 'Load older']) { const x = body.findOne((k) => k.name === n); if (x) x.visible = false; }
        const e = col(12, 'Empty'); pad(e, 16); e.cornerRadius = 14; e.fills = [fill('surface/raised')];
        e.appendChild(await text('Nothing in Sep 2026.', 'Body/Strong')); add(e, await text('Entries you add for these dates show up here.', 'Body/Regular', 'text/muted'));
        e.appendChild(await btn('Add a transaction', 'Primary/Medium')); add(body, e); refitClone(f);
      }],
      ['Transactions', 'Deleted · Undo', async (f) => {
        const s = K.snack.createInstance(); placeAbsolute(f, s, 16, f.height - 68 - 48 - s.height - 12);
      }],
      ['Add transaction', 'Saving', async (f) => {
        const ft = f.children.find((c) => c.name === 'Footer'); if (!ft) throw new Error('Footer not found');
        ft.children.forEach((c) => { c.visible = false; }); const s = K.saving.createInstance(); add(ft, s);
      }],
    ]],
  ];

  let y = 100, made = 0, maxX = 0;
  for (const [title, items] of rows) {
    const label = await text(title, 'Title/Screen'); sec.appendChild(label); label.x = 60; label.y = y;
    y += 60; let x = 60, rowH = 0;
    for (const [route, state, apply] of items) {
      const src = await routeFrame(route);
      const f = src.clone(); sec.appendChild(f); f.x = x; f.y = y; f.name = `${route} — ${state}`;
      f.setSharedPluginData('fintrackr', 'state-of', route);
      try { await apply(f); } catch (e) { log.push(`✗ ${f.name}: ${e.message}`); }
      x += 470; rowH = Math.max(rowH, f.height); made++; maxX = Math.max(maxX, x);
    }
    y += rowH + 140;
  }
  sec.resizeWithoutConstraints(maxX + 20, y);
  return `${made} state frames in “${sec.name}”`;
}
// Clones keep the route's fixed height; re-fit after changing content and stretch overlays to match.
function refitClone(f) {
  finalize(f);
  for (const o of f.children.filter((c) => c.name.startsWith('Overlay ·'))) { o.resize(390, f.height); for (const k of o.children) { if (k.name === 'Scrim') k.resize(390, f.height); else k.y = Math.max(0, f.height - k.height); } }
}

