async function readmeNotes() {
  const page = await figma.getNodeByIdAsync(PAGES.readme); await page.loadAsync();
  const root = page.children.find((n) => n.name === 'Read me'); if (!root) return 'Read me frame not found';
  root.children.filter((n) => n.name.startsWith('Round 6')).forEach((n) => n.remove());
  const p = col(14, 'Round 6 · sizes and state frames'); p.resize(1464, 100); p.primaryAxisSizingMode = 'AUTO'; p.counterAxisSizingMode = 'FIXED'; p.cornerRadius = 24; p.fills = [fill('surface/card')]; outline(p); pad(p, 32); add(root, p);
  add(p, await text('Round 6 · shorter pills, calmer type, state frames (24 Oct 2026)', 'Heading/Section'));
  for (const l of [
    'Pills look lighter: chips and segments 36px, medium buttons 40px, large 48px, top-bar action 40px. In code an invisible layer keeps every tap target at least 44px, so nothing gets harder to hit.',
    'Type steps down where it was loud: amount entry 40, balance 28, screen title 20, top-bar title 17, figures 16, section headings 15, labels 13. Body text stays 15/13.',
    'States now live in their own section, “07 · States (not routes)”, as real frames named “<Screen> — <State>”: popovers & sheets (transaction detail, delete, filters, period, record payment, pause, delete schedule, switch account); dropdowns & date pickers (Paid by for 3+ people, member search results / searching / no match, single date, custom range); loading & system (Home, Transactions, Recurring loading; offline; empty period; deleted with Undo; saving). The 32 route screens no longer carry hidden review layers.',
    'Dropdown rule: a short choice next to its field opens as a popover (listbox) anchored to it; a task with its own actions (detail, confirm, filters, pickers) opens as a bottom sheet.',
    ...log,
  ]) add(p, await text('• ' + l, 'Body/Regular', l.startsWith('✗') ? 'status/negative' : 'text/primary'));
  return `Read me → ${p.id}`;
}

(async () => {
  const results = [];
  try {
    await loadAllVars();
    await Promise.all([['DM Sans', 'Medium'], ['DM Sans', 'SemiBold'], ['DM Sans', 'Regular'], ['Space Grotesk', 'Medium'], ['Space Grotesk', 'Bold']].map(([family, style]) => figma.loadFontAsync({ family, style })));
    try { await figma.loadFontAsync({ family: 'Space Grotesk', style: 'SemiBold' }); } catch { /* Bold fallback from round 4 */ }
    for (const k of ['surface/active', 'overlay/scrim', 'brand/deep', 'text/disabled']) if (!vars[k]) throw new Error(`token ${k} missing — run rounds 4 and 5 first`);
  } catch (e) { figma.closePlugin(`Setup failed: ${e.message}`); return; }

  let dd = null;
  const steps = [
    ['Sizes', syncSizes],
    ['Clean route screens', cleanRoutes],
    ['Re-fit screens', refitRoutes],
    ['Dropdowns', async () => { dd = await buildDropdowns(); return `${Object.keys(dd).length} components`; }],
    ['States', () => buildStates(dd)],
    ['Read me', readmeNotes],
  ];
  const screensPage = await figma.getNodeByIdAsync(PAGES.screens);
  for (const [name, run] of steps) {
    try {
      if (['Clean route screens', 'Re-fit screens', 'States'].includes(name)) await figma.setCurrentPageAsync(screensPage);
      results.push(`✓ ${name}: ${await run()}`);
    } catch (e) { results.push(`✗ ${name}: ${e.message}`); }
  }
  await figma.setCurrentPageAsync(screensPage);
  console.log([...results, ...log].join('\n'));
  const failed = results.filter((r) => r.startsWith('✗')).length + log.filter((l) => l.startsWith('✗')).length;
  figma.closePlugin(failed ? `Round 6: ${failed} problem(s) — see the console (Plugins → Development → Show/Hide console)` : 'Round 6 applied: sizes, clean routes, 21 state frames');
})();
